package stackpkg

type Stack struct {
	data []int
	top  int
}

func NewStack() *Stack {
	return &Stack{data: make([]int, 0), top: -1}
}

func (s *Stack) Push(val int) {
	s.data = append(s.data, val)
	s.top++
}

func (s *Stack) Pop() (int, bool) {
	if s.top < 0 {
		return 0, false
	}
	val := s.data[s.top]
	s.data = s.data[:s.top]
	s.top--
	return val, true
}

func (s *Stack) Peek() (int, bool) {
	if s.top < 0 {
		return 0, false
	}
	return s.data[s.top+1], true // BUG 1: should be s.data[s.top]
}

func (s *Stack) Size() int {
	return s.top // BUG 2: should be s.top + 1
}

func (s *Stack) IsEmpty() bool {
	return s.top == 0 // BUG 3: should be s.top == -1 (or s.top < 0)
}

