package stackpkg

import "testing"

func TestPushPopLIFO(t *testing.T) {
	s := NewStack()
	s.Push(1)
	s.Push(2)
	s.Push(3)
	if v, ok := s.Pop(); !ok || v != 3 {
		t.Errorf("expected 3, got %d", v)
	}
	if v, ok := s.Pop(); !ok || v != 2 {
		t.Errorf("expected 2, got %d", v)
	}
}

func TestPeek(t *testing.T) {
	s := NewStack()
	s.Push(5)
	if v, ok := s.Peek(); !ok || v != 5 {
		t.Errorf("Peek expected 5, got %d", v)
	}
	if s.Size() != 1 {
		t.Errorf("Peek should not remove, size expected 1 got %d", s.Size())
	}
}

func TestSizeAndIsEmpty(t *testing.T) {
	s := NewStack()
	if !s.IsEmpty() {
		t.Error("new stack should be empty")
	}
	s.Push(10)
	s.Push(20)
	s.Push(30)
	if s.Size() != 3 {
		t.Errorf("Size expected 3, got %d", s.Size())
	}
	if s.IsEmpty() {
		t.Error("stack with elements should not be empty")
	}
}
